CameraBase::CameraBase(){SetGameConfigDistance();SetGameConfigAngle();current_.SetFovyDeg(45.0f);Instant();} CameraBase::~CameraBase()=default; void CameraBase::StartBlend(int n){blendFrame_=0;blendFrames_=fates::decomp_detail::CameraBaseBlendFrames(n);blendFrom_.CopyParam(&current_);} void CameraBase::StartShake(ProcInst*p,float power,int frames){fates::decomp_detail::CameraBaseShake(*this,p,power,frames,-1,0.0f,false);} void CameraBase::TickTarget(){UpdateTarget();if(targetFrame_<60)++targetFrame_;const float r=GetMoveRatio(targetFrame_);currentTarget_.x+=(destination_.x-currentTarget_.x)*r;currentTarget_.y+=(destination_.y-currentTarget_.y)*r;currentTarget_.z+=(destination_.z-currentTarget_.z)*r;} void CameraBase::UpdateAngle(){if(yaw_!=desiredYaw_)yawFrame_=0;if(pitch_!=desiredPitch_)pitchFrame_=0;} void CameraBase::TickDistance(){UpdateDistance();if(distanceFrame_<60)++distanceFrame_;const float r=GetMoveRatio(distanceFrame_);distance_+=(desiredDistance_-distance_)*r;} void CameraBase::SetDestinationF32(float x,float z){nn::math::VEC3 p{x,fates::decomp_detail::CameraBaseMapHeight(x,z),z};destination_=GetLimitTarget(p,0.0f);targetFrame_=0;} void CameraBase::UpdateTarget(){destination_=GetLimitTarget(destination_,0.0f);} void CameraBase::CalculateDraw(){fates::decomp_detail::CameraBaseCalculateDraw(*this);} void CameraBase::InstantConfig(){fates::decomp_detail::CameraBaseInstantConfig(*this);} void CameraBase::InstantTarget(){currentTarget_=destination_;targetFrame_=0;} void CameraBase::ShakeForCastle(ProcInst*p,float power,int frames,int curve,float extra){fates::decomp_detail::CameraBaseShake(*this,p,power,frames,curve,extra,true);} void CameraBase::UpdateDistance(){if(distance_!=desiredDistance_)distanceFrame_=0;} void CameraBase::SetDestinationInt(int x,int z){SetDestinationF32(static_cast<float>(x),static_cast<float>(z));} float CameraBase::GetGameConfigAngle(int i){return fates::decomp_detail::CameraBaseConfigAngle(i);} void CameraBase::SetGameConfigAll(){SetGameConfigDistance();SetGameConfigAngle();} void CameraBase::SetGameConfigAngle(){desiredYaw_=fates::decomp_detail::CameraBaseConfigAngle(0);desiredPitch_=fates::decomp_detail::CameraBaseConfigAngle(1);fates::decomp_detail::CameraBaseWriteConfigAngle(*this);} void CameraBase::SetFromCastleCamera(ICamera*c){fates::decomp_detail::CameraBaseImportCastle(*this,c);} float CameraBase::GetGameConfigDistance(int i){return fates::decomp_detail::CameraBaseConfigDistance(i);} void CameraBase::SetGameConfigDistance(){desiredDistance_=fates::decomp_detail::CameraBaseConfigDistance(0);fates::decomp_detail::CameraBaseWriteConfigDistance(*this);} void CameraBase::Tick(){TickTarget();TickDistance();TickAngle();TickBlend();Update();} void CameraBase::Shake(ProcInst*p,float power,int frames,int curve,float extra){fates::decomp_detail::CameraBaseShake(*this,p,power,frames,curve,extra,false);} void CameraBase::Update(){CalculateDraw();ICamera::Update();} void CameraBase::Instant(){InstantTarget();distance_=desiredDistance_;yaw_=desiredYaw_;pitch_=desiredPitch_;blendFrame_=blendFrames_=0;InstantConfig();Update();} void CameraBase::StopShake(int id,float fade){fates::decomp_detail::CameraBaseStopShake(*this,id,fade);} void CameraBase::TickAngle(){UpdateAngle();if(yawFrame_<60)++yawFrame_;if(pitchFrame_<60)++pitchFrame_;const float yr=GetMoveRatio(yawFrame_),pr=GetMoveRatio(pitchFrame_);yaw_+=(desiredYaw_-yaw_)*yr;pitch_+=(desiredPitch_-pitch_)*pr;SetRotateDeg(pitch_,yaw_,0.0f);} void CameraBase::TickBlend(){if(blendFrames_==0)return;blendFrame_+=1;if(blendFrame_>blendFrames_)blendFrame_=blendFrames_;const float t=static_cast<float>(blendFrame_)/static_cast<float>(blendFrames_);current_.BlendParam(&blendFrom_,&current_,t);if(blendFrame_>=blendFrames_)blendFrame_=blendFrames_=0;} bool CameraBase::IsBlending()const{return blendFrames_!=0;} float CameraBase::GetMoveRatio(int f)const{return fates::decomp_detail::CameraBaseMoveRatio(*this,f);} nn::math::VEC3 CameraBase::GetLimitTarget(const nn::math::VEC3&t,float m)const{return fates::decomp_detail::CameraBaseLimitTarget(*this,t,m);} bool CameraBase::IsAngleProlixity()const{return fates::decomp_detail::CameraBaseAngleProlixity(*this);} bool CameraBase::IsScrollProlixity()const{return fates::decomp_detail::CameraBaseScrollProlixity(*this);} bool CameraBase::IsDistanceProlixity()const{return fates::decomp_detail::CameraBaseDistanceProlixity(*this);} bool CameraBase::IsScroll()const{return targetFrame_>0&&targetFrame_<60;}
